<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('settings') ?></h1><div class="cards">
<section class="card"><h2><?= View::t('version') ?></h2><p><strong><?= View::e($currentVersion) ?></strong></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/update/check"><?= View::csrf() ?><button><?= View::t('check_updates') ?></button></form>
<?php if(is_array($update)): ?><p><?= $update['available'] ? View::e(View::t('new_version_available',['version'=>$update['latest']])) : View::t('up_to_date') ?></p><?php if($update['available']): ?><h3><?= View::t('update_changes') ?></h3><div class="update-changes"><?php if(!empty($update['commits'])): ?><ul><?php foreach($update['commits'] as $commit): ?><li><code><?= View::e($commit['sha']) ?></code> <?php if($commit['url']): ?><a href="<?= View::e($commit['url']) ?>" rel="noopener"><?= View::e($commit['message']) ?></a><?php else: ?><?= View::e($commit['message']) ?><?php endif; ?></li><?php endforeach; ?></ul><?php elseif(!empty($update['notes'])): ?><div class="release-notes"><?= nl2br(View::e($update['notes'])) ?></div><?php else: ?><p class="muted"><?= View::t('no_update_changes') ?></p><?php endif; ?></div><details><summary><?= View::t('install_version',['version'=>$update['latest']]) ?></summary><p class="muted"><?= View::t('update_backup_note') ?></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/update/install"><?= View::csrf() ?><input type="hidden" name="version" value="<?= View::e($update['latest']) ?>"><label><?= View::t('password') ?><input name="password" type="password" required autocomplete="current-password"></label><button><?= View::t('update_server') ?></button></form></details><?php endif; ?><?php endif; ?></section>
<section class="card"><h2><?= View::t('backup_restore') ?></h2><form method="post" action="<?= View::e($basePath) ?>/admin/settings/backup"><?= View::csrf() ?><button><?= View::t('create_download_backup') ?></button></form><h3><?= View::t('stored_backups') ?></h3><ul class="backup-list"><?php foreach($backups as $backup): ?><li><span><code><?= View::e($backup['name']) ?></code><small><?= View::e(number_format($backup['size']/1024,1,',',' ')) ?> KiB</small></span><form method="post" action="<?= View::e($basePath) ?>/admin/settings/backup/delete"><?= View::csrf() ?><input type="hidden" name="name" value="<?= View::e($backup['name']) ?>"><button class="danger-button action-button"><?= View::t('delete') ?></button></form></li><?php endforeach; ?><?php if(!$backups): ?><li><?= View::t('none') ?></li><?php endif; ?></ul><hr>
<details><summary><?= View::t('restore_backup') ?></summary><p class="notice error"><?= View::t('restore_warning') ?></p><form method="post" enctype="multipart/form-data" action="<?= View::e($basePath) ?>/admin/settings/restore"><?= View::csrf() ?><label><?= View::t('backup_file') ?><input name="backup" type="file" accept=".zip,application/zip" required></label><label><?= View::t('password') ?><input name="password" type="password" required autocomplete="current-password"></label><button><?= View::t('restore_data') ?></button></form></details></section>
<section class="card"><h2><?= View::t('security') ?></h2><?php if(!$securityIssues): ?><p class="notice success"><?= View::t('security_ok') ?></p><?php else: ?><ul><?php foreach($securityIssues as $issue): ?><li><?= View::e($issue) ?></li><?php endforeach; ?></ul><?php endif; ?><p class="muted"><?= View::t('document_root_help') ?></p></section>
<?php $activeDevices=array_values(array_filter($devices,static fn(array $device):bool=>!$device['revoked_at']));$revokedDevices=array_values(array_filter($devices,static fn(array $device):bool=>(bool)$device['revoked_at'])); ?>
<section class="card settings-devices"><h2><?= View::t('connected_devices') ?></h2><p class="muted"><?= View::t('connected_devices_help') ?></p><div class="table-wrap"><table><thead><tr><th><?= View::t('device') ?></th><th><?= View::t('user') ?></th><th><?= View::t('app_version') ?></th><th><?= View::t('last_seen') ?></th><th><?= View::t('status') ?></th><th></th></tr></thead><tbody><?php foreach($activeDevices as $device): ?><tr><td><strong><?= View::e($device['name']) ?></strong><br><small><?= View::e($device['platform']) ?></small></td><td><?= View::e($device['display_name']?:$device['username']) ?></td><td><?= View::e($device['app_version']?:'—') ?></td><td><?= View::e($device['last_seen_at']?:$device['created_at']) ?> UTC</td><td><?= View::t('connected') ?></td><td><details><summary><?= View::t('revoke') ?></summary><p class="muted"><?= View::t('revoke_device_help') ?></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/device/revoke"><?= View::csrf() ?><input type="hidden" name="id" value="<?= View::e($device['id']) ?>"><button class="danger-button action-button"><?= View::t('revoke_device') ?></button></form></details></td></tr><?php endforeach; ?><?php if(!$activeDevices): ?><tr><td colspan="6"><?= View::t('no_connected_devices') ?></td></tr><?php endif; ?></tbody></table></div><?php if($revokedDevices): ?><details class="revoked-devices"><summary><?= View::t('revoked_devices',['count'=>count($revokedDevices)]) ?></summary><form method="post" action="<?= View::e($basePath) ?>/admin/settings/devices/delete-revoked"><?= View::csrf() ?><button class="danger-button action-button"><?= View::t('delete_all_revoked') ?></button></form><div class="table-wrap"><table><thead><tr><th><?= View::t('device') ?></th><th><?= View::t('user') ?></th><th><?= View::t('app_version') ?></th><th><?= View::t('last_seen') ?></th><th></th></tr></thead><tbody><?php foreach($revokedDevices as $device): ?><tr><td><strong><?= View::e($device['name']) ?></strong><br><small><?= View::e($device['platform']) ?></small></td><td><?= View::e($device['display_name']?:$device['username']) ?></td><td><?= View::e($device['app_version']?:'—') ?></td><td><?= View::e($device['last_seen_at']?:$device['created_at']) ?> UTC</td><td><form method="post" action="<?= View::e($basePath) ?>/admin/settings/device/delete"><?= View::csrf() ?><input type="hidden" name="id" value="<?= View::e($device['id']) ?>"><button class="danger-button action-button"><?= View::t('delete') ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?></section>
<section class="card settings-devices"><h2><?= View::t('server_diagnostics') ?></h2><p class="muted"><?= View::t('server_diagnostics_help') ?></p><?php if($recentErrors): ?><pre class="diagnostic-log"><?php foreach($recentErrors as $line): ?><?= View::e($line) ?>
<?php endforeach; ?></pre><?php else: ?><p><?= View::t('no_server_errors') ?></p><?php endif; ?></section></div>
